"""Determine if the round is fast or slow.

    :meta private:
    """
def is_fast_round(rnd: int, r_fast: int, r_slow: int) -> bool {
    remainder = rnd % (r_fast + r_slow);
    return ((remainder - r_fast) < 0);
}

"""Given the first pass code, generate any labels"""
def calculate_labels(first_pass: Any) -> object {
    address = 0;
    labels = {};
    for (label, instruction) in first_pass {
        if label {
            labels[label] = address;
        }
        address += len(instruction);
    }
    return labels;
}

